        let mut enc = A::encoder_new()
        enc.reserve_head(T::ENCODED_SIZE)
        value.encode(mut enc)
        let out: (u256, u256) = enc.finish()
        self.return_bytes(ptr: out.0, len: out.1)
    }
}

