impl<S: IntWord, T: IntWord> IntDowncast<T> for S {
    fn downcast(self) -> Option<T> {
        let word = self.to_word()
        if T::IS_SIGNED {
            let t_min_word = sign_extend(word: T::SIGN_BIT, mask: T::MASK, sign_bit: T::SIGN_BIT)
            let t_max_word = T::SIGN_BIT - 1
            let t_min: i256 = __bitcast(t_min_word)
            let t_max: i256 = __bitcast(t_max_word)

            if !S::IS_SIGNED && (word & I256_SIGN_BIT != 0) {
                Option::None
            } else {
                let x: i256 = __bitcast(word)
                if x < t_min {
                    Option::None
                } else if x > t_max {
                    Option::None
                } else {
                    Option::Some(T::from_word(word))
                }
            }
        } else {
            if S::IS_SIGNED && (word & I256_SIGN_BIT != 0) {
                Option::None
            } else if word > T::MASK {
                Option::None
            } else {
                Option::Some(T::from_word(word))
            }
        }
    }

    fn downcast_truncate(self) -> T {
        let word = self.to_word()
        if T::IS_SIGNED {
            T::from_word(sign_extend(word: word, mask: T::MASK, sign_bit: T::SIGN_BIT))
        } else {
            T::from_word(word & T::MASK)
        }
    }

    fn downcast_saturate(self) -> T {
        let word = self.to_word()
        if !T::IS_SIGNED {
            let mut unsigned_word = word
            if S::IS_SIGNED && (word & I256_SIGN_BIT != 0) {
                unsigned_word = 0
            }

            if unsigned_word > T::MASK {
                T::from_word(T::MASK)
            } else {
                T::from_word(unsigned_word)
            }
        } else {
            let t_min_word = sign_extend(word: T::SIGN_BIT, mask: T::MASK, sign_bit: T::SIGN_BIT)
            let t_max_word = T::SIGN_BIT - 1
            let t_min: i256 = __bitcast(t_min_word)
            let t_max: i256 = __bitcast(t_max_word)

            if S::IS_SIGNED {
                let x: i256 = __bitcast(word)
                if x < t_min {
                    T::from_word(t_min_word)
                } else if x > t_max {
                    T::from_word(t_max_word)
                } else {
                    T::from_word(word)
                }
            } else {
                if word & I256_SIGN_BIT != 0 {
                    T::from_word(t_max_word)
                } else {
                    let x: i256 = __bitcast(word)
                    if x > t_max {
                        T::from_word(t_max_word)
                    } else {
                        T::from_word(word)
                    }
                }
            }
        }
    }

    fn downcast_unchecked(self) -> T {
        let word = self.to_word()
        T::from_word(word)
    }
}

/// Performs two's-complement sign extension within the provided mask/sign bit.
pub fn sign_extend(word: u256, _ mask: u256, _ sign_bit: u256) -> u256 {
    let value = word & mask
    if value & sign_bit != 0 {
        value | (U256_MASK ^ mask)
    } else {
        value
    }
}

fn pow_checked<T>(_ base: own T, _ exp: own T) -> T
    where T: IntWord, T: Mul<Output = T>
{
    let exp_word = exp.to_word() & T::MASK
    if T::IS_SIGNED && (exp_word & T::SIGN_BIT != 0) {
        panic()
    }

    let mut acc_word: u256 = 1
    let mut base_word: u256 = base.to_word()
    let mut exp_word = exp_word

    while exp_word > 0 {
        if (exp_word & 1) != 0 {
            acc_word = T::from_word(acc_word).mul(T::from_word(base_word)).to_word()
        }
        exp_word = exp_word >> 1
        if exp_word > 0 {
            base_word = T::from_word(base_word).mul(T::from_word(base_word)).to_word()
        }
    }
    T::from_word(acc_word)
}

