    let mask = ((1 as u256) << bits) - 1
    let sign_bit = (1 as u256) << (bits - 1)
    let value = word & mask

    if value & sign_bit != 0 {
        let canonical = value | (FULL_WORD_MASK ^ mask)
        if canonical == word {
            return canonical
        }
        revert(offset: 0, len: 0)
    }

    if value == word {
        return value
    }

    revert(offset: 0, len: 0)
}

