    ops::mstore(addr: ptr + 128, value: exp)
    ops::mstore(addr: ptr + 160, value: modulus)
    let ok: u256 = ops::staticcall(
        gas: ops::gas(),
        addr: 5,
        args_offset: ptr,
        args_len: 192,
        ret_offset: ptr,
        ret_len: 32,
    )
    assert_precompile_ok(ok, 32)
    ops::mload(ptr)
}

