use core::effect_ref::{EffectHandle, EffectHandleMut, EffectRef, EffectRefMut}
use core::{size_of}
use core::abi::{Abi, AbiDecoder, AbiEncoder, AbiSize, AbiSpan, Decode, Encode, abi_root_head_size, encode_root}
