                at: tail_at + offset_in_payload,
                value: mem_word_at(base: self.data, offset: offset_in_payload),
            )
            offset_in_payload += 32
        }
    }

    fn encode_to_ptr(own self, _ ptr: u256) {
        super::panic()
    }
}

