    where T: AbiSize
{
    const DIRECT_ENCODE: bool = false

    fn encode<E: AbiEncoder<A>>(own self, _ e: mut E) {
        let tail_at = e.append_tail(self.size)
        let offset = tail_at - e.base()

        e.write_word(offset)
        if self.data == 0 {
            e.write_word_at(at: tail_at, value: self.len)
            return
        }

        let mut offset_in_payload: u256 = 0
        while offset_in_payload < self.size {
            e.write_word_at(
                at: tail_at + offset_in_payload,
                value: mem_word_at(base: self.data, offset: offset_in_payload),
            )
            offset_in_payload += 32
        }
    }

    fn encode_to_ptr(own self, _ ptr: u256) {
        super::panic()
    }
}

